<template>
  <div class="panel sub">
    <div class="subhead">
      <span class="back" @click="$router.push('/')"><i class="bi bi-arrow-left"></i></span>
      <span class="ttl">{{ this.$store.state.locales.nui_rewards }}</span>
    </div>
    <div class="subbody">
      <div class="box">
        <div class="bh">
          <span class="bt">{{ leveldata.level }}. {{ this.$store.state.locales.nui_level }}</span>
          <span class="bs">{{ leveldata.xp }} / {{ leveldata.nextxp }} {{ this.$store.state.locales.nui_xp }}</span>
        </div>
        <div class="xpbar">
          <div class="xpbar-fill" :style="{ width: leveldata.percent + '%' }"></div>
        </div>
      </div>

      <div class="box">
        <div class="bh">
          <span class="bt">{{ this.$store.state.locales.nui_rewards }}</span>
          <span class="bs">{{ this.$store.state.locales.nui_rewards_desc }}</span>
        </div>
        <div class="rewards-grid">
          <div
            v-for="level in levels"
            :key="level.id"
            class="reward-card"
            :class="{ 'reward-claimed': level.claimed, 'reward-locked': level.locked }"
            @click="claimLevel(level.id)"
          >
            <span class="reward-badge" v-if="level.claimed"><i class="bi bi-check-lg"></i></span>
            <span class="reward-badge" v-else-if="level.locked"><i class="bi bi-lock-fill"></i></span>
            <span class="reward-level">#{{ level.id }}</span>
            <img :src="level.img" alt="">
            <span class="reward-label">{{ level.label }}</span>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: 'Xp',
  data() {
    return {
      leveldata: {
        level:1,
        xp:0,
        nextlevel:2,
        nextxp:300,
        percent:0
      },
      levels: []
    }
  },
  methods: {
    async updateState() {
      const response = await fetch(`https://${this.$getResource()}/getlevels`);
      const data = await response.json();
      if (!data) return;
      this.levels = data.levels;
      this.leveldata = data.leveldata;
    },
    claimLevel(level) {
      fetch(`https://${this.$getResource()}/claimlevel`, {
        method: 'POST',
        body: JSON.stringify({
          level : level
        })
      });
    }
  },
  mounted() {
    this.updateState()
  }
}
</script>

