<template>
  <div id="cont">
    <router-view/>
  </div>
</template>

<script>
export default {
  name: 'App',
  methods: {
    exit() {
      fetch(`https://${this.$getResource()}/exit`);
    },
    onkey(evt) {
      evt = evt || window.event;
      if (evt.keyCode == 27) {
        this.exit();
      }
    },
    onmessage(event) {
      const eventType = event.data.action
      if (eventType == "show") {
        document.body.style.display = event.data.enable ? "block" : "none";
        this.$router.push('/nothing')
        if (event.data.enable) {
          this.$router.push('/')
          this.$store.dispatch('fetchVip', this.$getResource())
        }
      }
    }
  },
  async created() {
    document.onkeydown = this.onkey
    window.addEventListener('message', this.onmessage)
    const response = await fetch(`https://${this.$getResource()}/getlocales`);
    const data = await response.json();
    if (!data) return;
    this.$store.commit("setLocales", data)
    this.$store.dispatch('fetchVip', this.$getResource())
  }
}
</script>


