<template>
  <div class="panel sub">
    <div class="subhead">
      <span class="back" @click="$router.push('/')"><i class="bi bi-arrow-left"></i></span>
      <span class="ttl">{{ this.$store.state.locales.nui_menus }}</span>
    </div>
    <div class="subbody">
      <div class="box menu-list">
        <div class="menu-row" v-for="menu in menus" :key="menu.id" @click="openMenu(menu.id)">
          <div class="ico"><img :src="menu.img" alt=""></div>
          <div class="lbl">
            <div class="t">{{ menu.label }}</div>
            <div class="d">{{ menu.desc }}</div>
          </div>
          <i class="bi bi-chevron-right arrow"></i>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: 'Menus',
  data() {
    return {
      menus: []
    }
  },
  methods: {
    openMenu(menu) {
      fetch(`https://${this.$getResource()}/openmenu`, {
        method: 'POST',
        body: JSON.stringify({
          menu : menu
        })
      });
    }
  },
  async mounted() {
    const response = await fetch(`https://${this.$getResource()}/getmenus`);
    const data = await response.json();
    if (!data) return;
    this.menus = data.menus;
  }
}
</script>

