<template>
  <div class="panel home">
    <div class="card vip">
      <div class="t">{{ this.$store.state.locales.nui_label }}</div>
      <div class="sub">{{ vip.label }}</div>
      <div class="badge" v-if="hasVip">{{ vip.level }}. {{ this.$store.state.locales.nui_level }} / {{ vip.xp }} {{ this.$store.state.locales.nui_xp }}</div>
      <div class="d exp" v-if="hasVip">{{ this.$store.state.locales.nui_experation }} {{ vip.until }}</div>
      <div class="actions" v-if="hasVip">
        <span class="link" @click="toggleAutorenew">{{ this.$store.state.locales.nui_autorenew }}: {{ autorenewInfo.autorenew ? this.$store.state.locales.nui_autorenew_on : this.$store.state.locales.nui_autorenew_off }}</span>
        <span class="link danger" @click="cancelVip">{{ confirmingCancel ? this.$store.state.locales.nui_cancel_confirm : this.$store.state.locales.nui_cancel_vip }}</span>
      </div>
      <img class="art" src="../assets/michael.png" alt="">
    </div>

    <div class="card gift" @click="claimDalygift">
      <div class="t">{{ this.$store.state.locales.nui_dalygift }}</div>
      <div class="d">{{ dalygift }}</div>
      <img class="art" src="../assets/gift.png" alt="">
    </div>

    <div class="card rewards" @click="$router.push('/xp')">
      <div class="t">{{ this.$store.state.locales.nui_rewards }}</div>
      <div class="d">{{ this.$store.state.locales.nui_rewards_desc }}</div>
      <img class="art" src="../assets/crates.png" alt="">
    </div>

    <div class="card menus" @click="$router.push('/menus')">
      <div class="t">{{ this.$store.state.locales.nui_menus }}</div>
      <div class="d">{{ this.$store.state.locales.nui_menus_desc }}</div>
      <img class="art" src="../assets/trevor.png" alt="">
    </div>
  </div>
</template>

<script>
export default {
  name: 'Home',
  data() {
    return {
      dalygift: "",
      autorenewInfo: {
        autorenew: false,
        price: 0,
        currency: "money",
        label: ""
      },
      confirmingCancel: false
    }
  },
  computed: {
    vip() {
      return this.$store.state.vip
    },
    hasVip() {
      return this.vip.label !== "-";
    }
  },
  methods: {
    async updateState() {
      const data = await this.$store.dispatch('fetchVip', this.$getResource());
      if (!data) return;
      this.dalygift = data.dalygift;
    },
    async loadAutorenewInfo() {
      const response = await fetch(`https://${this.$getResource()}/getautorenewinfo`);
      const data = await response.json();
      if (!data) return;
      this.autorenewInfo = data;
    },
    claimDalygift() {
      fetch(`https://${this.$getResource()}/dalygift`)
    },
    async toggleAutorenew() {
      const response = await fetch(`https://${this.$getResource()}/toggleautorenew`);
      const data = await response.json();
      this.autorenewInfo.autorenew = data === true;
    },
    async cancelVip() {
      if (!this.confirmingCancel) {
        this.confirmingCancel = true;
        setTimeout(() => { this.confirmingCancel = false; }, 3000);
        return;
      }
      this.confirmingCancel = false;
      await fetch(`https://${this.$getResource()}/cancelvip`);
      this.updateState();
      this.loadAutorenewInfo();
    }
  },
  mounted() {
    this.updateState()
    this.loadAutorenewInfo()
  },
}
</script>

