import { createStore } from 'vuex'

export default createStore({
  state: {
    locales: {
      "nui_label":"VIP",
      "nui_level":"level",
      "nui_xp":"XP",
      "nui_experation":"VIP until:",
      "nui_dalygift":"Daly Gift",
      "nui_rewards":"Rewards",
      "nui_rewards_desc":"Here you can find the rewards",
      "nui_menus":"Menus",
      "nui_menus_desc":"Here you can find the extra menus, only for VIPs",
    },
    vip: {
      label: "-",
      level: 1,
      xp: 0,
      until: "0000/00/00 00:00"
    }
  },
  mutations: {
    setLocales(state, payload) {
      state.locales = payload
    },
    setVip(state, payload) {
      state.vip = payload
    }
  },
  actions: {
    async fetchVip({ commit }, getResource) {
      const response = await fetch(`https://${getResource}/getvip`);
      const data = await response.json();
      if (!data) return null;
      commit('setVip', data.vipobj)
      return data
    }
  },
  modules: {
  }
})
